using Axis.Extensions;

namespace $name;

/// <summary>Returns the text it is given. It is the first operation of a new package.</summary>
public sealed class EchoOperation : IOperation
{
    public Task<IReadOnlyDictionary<string, object?>> RunAsync(
        IReadOnlyDictionary<string, object?> input,
        IOperationContext context,
        CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(input);

        IReadOnlyDictionary<string, object?> output = new Dictionary<string, object?>
        {
            ["text"] = input["text"],
        };
        return Task.FromResult(output);
    }
}

